import re

def parse_range(header, size):
    if not header or 'bytes=' not in header:
        return None

    try:
        ranges_str = header.split('bytes=')[1].split(',')[0]
        if not ranges_str:
            return None

        raw_ranges = ranges_str.split(',')
        results = []
        any_satisfiable = False

        for r in raw_ranges:
            r = r.strip()
            if not r:
                continue

            try:
                if '-' in r:
                    parts = r.split('-')
                    start_str = parts[0].strip()
                    end_str = parts[1].strip() if len(parts) > 1 else ""

                    # Handle suffix (e.g., -500)
                    if start_str.startswith('-'):
                        suffix_len = int(start_str[1:])
                        start = max(0, size - suffix_len)
                        end = size - 1
                    else:
                        start = int(start_str)
                        if end_str == "":
                            end = size - 1
                        else:
                            end = int(end_str)
                else:
                    # Single point (e.g., 500)
                    start = int(r)
                    end = start

                # Validation and Clamping
                if start >= size:
                    continue

                actual_start = max(0, start)
                actual_end = min(size - 1, end)

                if actual_start <= actual_end:
                    results.append((actual_start, actual_end))
                    any_satisfiable = True
                else:
                    # This specific range is unsatisfiable (e.g. 1000-500)
                    pass
            except ValueError:
                return None

        return results if any_satisfiable else None
    except Exception:
        return None
```

