class TrieNode:
    def __init__(self):
        self.children = {}
        self.count = 0

class WildcardTrie:
    def __init__(self):
        self.root = TrieNode()

    def add(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.count += 1

    def remove(self, word: str) -> bool:
        node = self.root
        path = [node]
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
            path.append(node)

        if node.count > 0:
            node.count -= 1
            return True
        return False

    def search(self, pattern: str) -> list[str]:
        results = []

        def dfs(node, index, current_word):
            if index == len(pattern):
                if node.count > 0:
                    results.append(current_word)
                return

            char = pattern[index]
            if char == '.':
                for next_char, next_node in node.children.items():
                    dfs(next_node, index + 1, current_word + next_char)
            else:
                if char in node.children:
                    dfs(node.children[char], index + 1, current_word + char)

        dfs(self.root, 0, "")
        return sorted(results)
