import re

def natural_key(s):
    def convert(text):
        if text.isdigit():
            # Return a tuple: (is_digit, numeric_value, original_length)
            # is_digit=1 ensures numbers are sorted after non-digits if needed,
            # but since we want "file manager" style, we treat numbers as 
            # distinct units. To handle "shorter zero-padded runs sort first",
            # we include the length of the string.
            return (1, int(text), len(text))
        else:
            # Return a tuple: (is_digit=0, lowercase_text, original_case_text)
            # The lowercase text is the primary comparison, 
            # original_case_text breaks ties.
            return (0, text.lower(), text)

    # Split by digits, keeping the digits in the result
    parts = re.split(r'(\d+)', s)
    return [convert(part) for part in parts if part]
```

