        buffer += chunk
        cursor = 0
        while cursor < len(buffer):
            # Handle Row Endings
            if not in_quotes:
                if buffer[cursor:cursor+2] == "\r\n":
                    # Check if it's a true CRLF or just a newline
                    # RFC 4180 says CRLF, but we handle \n and \r as well
                    # to be robust to different line endings.
                    # However, the prompt specifies \r\n, \n, and \r.
                    pass 

                # Look for any of the three line endings
                found_newline = False
                if buffer[cursor:cursor+2] == "\r\n":
                    line_end = cursor + 2
                    found_newline = True
                elif buffer[cursor] == "\n":
                    line_end = cursor + 1
                    found_newline = True
                elif buffer[cursor] == "\r":
                    line_end = cursor + 1
                    found_newline = True

                if found_newline:
                    # Process the line accumulated so far
                    line = buffer[:line_end]
                    yield _parse_line(line)
                    buffer = buffer[line_end:]
                    cursor = 0
                    continue

            # Handle Quoted Fields and Escaped Quotes
            if buffer[cursor] == '"':
                if not in_quotes:
                    # Start of a quoted field
                    in_quotes = True
                    cursor += 1
                else:
                    # Inside a quoted field, check for escaped quote ""
                    if cursor + 1 < len(buffer) and buffer[cursor+1] == '"':
                        # It's an escaped quote
                        cursor += 2
                    else:
                        # It's the closing quote
                        in_quotes = False
                        cursor += 1
            else:
                cursor += 1

    # Final processing for the last line if no trailing newline
    if buffer:
        if in_quotes:
            raise ValueError("Document ends inside an unterminated quoted field.")
        yield _parse_line(buffer)

