function pLimit(n) {
  const queue = [];
  let activeCount = 0;

  const next = () => {
    if (queue.length === 0) return;

    activeCount--;
    const { task, resolve, reject } = queue.shift();

    task()
      .then(resolve)
      .catch(reject)
      .finally(() => {
        next();
      });
  };

  return function(task) {
    return new Promise((resolve, reject) => {
      queue.push({ task, resolve, reject });

      if (activeCount < n) {
        activeCount++;
        next();
      }
    });
  };
}

module.exports = pLimit;
