  const visited = new WeakMap();

  function compare(x, y) {
    if (x === y) return true;
    if (typeof x !== 'object' || x === null || typeof y !== 'object' || y === null) return false;

    // Check for cycles
    if (visited.has(x) && visited.has(y)) return true;
    visited.set(x, y);

