const decode = (str) => {
  return str.replace(/~1/g, '/').replace(/~0/g, '~');
};

const get = (doc, pointer) => {
  if (pointer !== "" && !pointer.startsWith("/")) {
    throw new Error("Pointer must start with '/' or be empty");
  }
  if (pointer === "") return doc;

  const parts = pointer.split("/").slice(1);
  let current = doc;

  for (const part of parts) {
    if (current === null || typeof current !== "object") return undefined;
    const decoded = decode(part);

    if (Array.isArray(current)) {
      const index = parseInt(decoded, 10);
      if (isNaN(index) || index < 0 || index >= current.length) return undefined;
      current = current[index];
    } else {
      if (!(decoded in current)) return undefined;
      current = current[decoded];
    }
  }
  return current;
};

const set = (doc, pointer, value) => {
  if (pointer !== "" && !pointer.startsWith("/")) {
    throw new Error("Pointer must start with '/' or be empty");
  }
  if (pointer === "") return value;

  const parts = pointer.split("/").slice(1);
  let current = doc;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const decoded = decode(part);
    const isLast = i === parts.length - 1;

    if (isLast) {
      if (Array.isArray(current)) {
        const index = parseInt(decoded, 10);
        if (!isNaN(index) && index >= current.length) {
          current[index] = value;
        } else if (!isNaN(index)) {
          current[index] = value;
        } else {
          current.push(value);
        }
      } else {
        current[decoded] = value;
      }
    } else {
      if (!(decoded in current) || current[decoded] === null || typeof current[decoded] !== "object") {
        current[decoded] = Array.isArray(current) ? [] : {};
      }
      current = current[decoded];
    }
  }
  return doc;
};

module.exports = { get, set };
