export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, Array<((payload: any) => void)>>();

  on<K extends keyof E>(
    key: K,
    handler: (payload: E[K] extends void ? undefined : E[K]) => void
  ): () => void {
    if (!this.handlers.has(key)) {
      this.handlers.set(key, []);
    }

    const handlersList = this.handlers.get(key)!;
    handlersList.push(handler);

    return () => {
      const list = this.handlers.get(key);
      if (list) {
        const index = list.indexOf(handler);
        if (index !== -1) list.splice(index, 1);
      }
    };
  }

  emit<K extends keyof E>(
    key: K,
    ...args: E[K] extends void ? [] : [payload: E[K]]
  ): void {
    const handlers = this.handlers.get(key);
    if (!handlers) return;

    const payload = args.length > 0 ? args[0] : undefined;
    handlers.forEach((handler) => handler(payload));
  }
}
