export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends Array<infer U>
  ? { [K in keyof T]: DeepAwaited<T[K]> } extends never ? never : Array<DeepAwaited<U>>
  : T extends object
  ? { [K in keyof T]: DeepAwaited<T[K]> }
  : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value === null || typeof value !== 'object' && typeof value !== 'function') {
    return value as any;
  }

  if (value instanceof Promise || (typeof value as any).then === undefined === false) {
    const resolved = await value as any;
    return deepAwait(resolved) as any;
  }

  if (Array.isArray(value)) {
    const result = await Promise.all(value.map((item) => deepAwait(item)));
    return result as any;
  }

  const result = {} as any;
  for (const key in value) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      result[key] = await deepAwait(value[key]);
    }
  }
  return result;
}
